import { useState, type FormEvent } from 'react';
import { JxButton, JxInputField, JxSelect, JxSwitch } from '@jinx-ui/react';

export interface ProfileSettings {
  name: string;
  language: string;
  emailNotifications: boolean;
}

interface ProfileSettingsFormProps {
  initialValue?: ProfileSettings;
  onSave: (settings: ProfileSettings) => void;
}

const languages = [
  { value: 'ru', label: 'Русский' },
  { value: 'en', label: 'English' },
];

export default function ProfileSettingsForm({ initialValue, onSave }: ProfileSettingsFormProps) {
  const [name, setName] = useState(initialValue?.name ?? '');
  const [language, setLanguage] = useState(initialValue?.language ?? 'ru');
  const [emailNotifications, setEmailNotifications] = useState(initialValue?.emailNotifications ?? false);
  const [submitted, setSubmitted] = useState(false);

  const trimmedName = name.trim();
  const nameError = submitted && trimmedName.length === 0 ? 'Укажите имя' : undefined;

  const submit = (event: FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    setSubmitted(true);
    if (trimmedName.length === 0) return;
    onSave({ name: trimmedName, language, emailNotifications });
  };

  return (
    <form
      onSubmit={submit}
      style={{ display: 'grid', gap: '16px', maxWidth: '420px', fontFamily: 'var(--jx-font-sans)' }}
    >
      <JxInputField
        label="Имя"
        name="name"
        required
        autoComplete="name"
        placeholder="Как к вам обращаться"
        value={name}
        onChange={(event) => setName(event.target.value)}
        errorText={nameError}
      />

      <JxSelect
        label="Язык интерфейса"
        options={languages}
        value={language}
        onValueChange={setLanguage}
        placeholder="Выберите язык"
      />

      <JxSwitch
        label="Уведомления на почту"
        name="emailNotifications"
        checked={emailNotifications}
        onChange={(event) => setEmailNotifications(event.target.checked)}
      />

      <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
        <JxButton type="submit" variant="primary">
          Сохранить
        </JxButton>
      </div>
    </form>
  );
}

